package com.frezzamusic.app.data
import android.util.Base64
object ArtistLogos {
 private const val FREZZA=""
 private const val SOLASIAS=""
 fun forArtist(name:String):ByteArray?=when(name.lowercase()){ "thefrezza"->Base64.decode(FREZZA,Base64.DEFAULT); "solasias"->Base64.decode(SOLASIAS,Base64.DEFAULT); else->null }
}